declare(strict_types=1);require __DIR__.'/app/bootstrap.php';if(Auth::check()){header('Location: '.Auth::homePath());exit;}$pdo=Database::connection();Auth::ensureUserSchema();ensure_member_soft_delete_schema($pdo);$pdo->exec("CREATE TABLE IF NOT EXISTS member_activation_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,member_id INT UNSIGNED NOT NULL,code_hash CHAR(64) NOT NULL UNIQUE,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_by_user_id INT UNSIGNED NULL,INDEX idx_mac_member(member_id),INDEX idx_mac_expiry(expires_at),CONSTRAINT fk_mac_member FOREIGN KEY(member_id) REFERENCES members(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
$step=1;$err='';$member=null;$codeId=0;if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=(string)($_POST['action']??'lookup');try{if($action==='lookup'){$first=trim((string)($_POST['first_name']??''));$raw=strtoupper(preg_replace('/[^A-Z0-9]/i','',(string)($_POST['code']??'')));if($first===''||strlen($raw)!==8)throw new RuntimeException('Controleer je voornaam en activatiecode.');$q=$pdo->prepare('SELECT ac.id code_id,m.* FROM member_activation_codes ac JOIN members m ON m.id=ac.member_id WHERE ac.code_hash=:h AND ac.used_at IS NULL AND ac.expires_at>NOW() AND m.deleted_at IS NULL LIMIT 1');$q->execute(['h'=>hash('sha256',$raw)]);$member=$q->fetch();if(!$member||mb_strtolower(trim($member['first_name']))!==mb_strtolower($first))throw new RuntimeException('Voornaam of activatiecode is niet correct.');$_SESSION['activation_member_id']=(int)$member['id'];$_SESSION['activation_code_id']=(int)$member['code_id'];$step=2;}else{$mid=(int)($_SESSION['activation_member_id']??0);$cid=(int)($_SESSION['activation_code_id']??0);$q=$pdo->prepare('SELECT m.*,ac.id code_id FROM members m JOIN member_activation_codes ac ON ac.member_id=m.id WHERE m.id=:mid AND ac.id=:cid AND ac.used_at IS NULL AND ac.expires_at>NOW()');$q->execute(['mid'=>$mid,'cid'=>$cid]);$member=$q->fetch();if(!$member)throw new RuntimeException('Deze activatie is verlopen. Vraag een nieuwe code.');$email=strtolower(trim((string)($_POST['email']??'')));$birth=(string)($_POST['birth_date']??'');$weight=(float)str_replace(',','.',(string)($_POST['weight_kg']??''));$mobile=trim((string)($_POST['mobile']??''));$pw=(string)($_POST['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||$birth===''||$weight<=0||strlen($pw)<10)throw new RuntimeException('E-mail, geboortedatum, geldig gewicht en een wachtwoord van minstens 10 tekens zijn verplicht.');$pdo->beginTransaction();$pdo->prepare('UPDATE members SET email=:e,birth_date=:b,weight_kg=:w,mobile=:mob WHERE id=:id')->execute(['e'=>$email,'b'=>$birth,'w'=>$weight,'mob'=>$mobile?:null,'id'=>$mid]);$exists=$pdo->prepare('SELECT id FROM users WHERE member_id=:id');$exists->execute(['id'=>$mid]);if($exists->fetchColumn())throw new RuntimeException('Voor dit lid bestaat al een account.');$pdo->prepare('INSERT INTO users(member_id,name,email,password_hash,role,is_active) VALUES(:mid,:n,:e,:h,"member",1)')->execute(['mid'=>$mid,'n'=>trim($member['first_name'].' '.$member['last_name']),'e'=>$email,'h'=>password_hash($pw,PASSWORD_DEFAULT)]);$pdo->prepare('UPDATE member_activation_codes SET used_at=NOW() WHERE id=:id')->execute(['id'=>$cid]);$pdo->commit();unset($_SESSION['activation_member_id'],$_SESSION['activation_code_id']);header('Location: /login.php?activated=1');exit;}}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$err=$e->getMessage();if($action==='complete')$step=2;}}
?><!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Eerste aanmelding | Heli One</title><style>body{font-family:Arial,sans-serif;background:#f3f5f7;margin:0;display:grid;place-items:center;min-height:100vh}.card{width:min(500px,calc(100% - 40px));background:#fff;padding:30px;border-radius:16px;box-shadow:0 12px 40px #0001}.logo{display:block;width:min(280px,80%);margin:0 auto 25px}label{display:block;font-weight:700;margin:14px 0 5px}input{width:100%;box-sizing:border-box;padding:12px;border:1px solid #cbd2d9;border-radius:8px}button{width:100%;padding:13px;border:0;border-radius:9px;background:#111;color:#fff;font-weight:700;margin-top:20px}.err{background:#feecec;padding:11px}.muted{color:#68707a}.pw{display:flex;gap:6px}.pw button{width:48px;margin-top:0;background:#e8ebef;color:#111}</style></head><body><main class="card"><img class="logo" src="/assets/HeliOne%20-%20Logo%20-%20zwart.png" alt="Heli One"><h1>Eerste aanmelding</h1><?php if($err):?><p class="err"><?=e($err)?></p><?php endif;?><?php if($step===1):?><p class="muted">Gebruik je voornaam en de persoonlijke activatiecode die je van Heli One of je organisatie kreeg.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="lookup"><label>Voornaam</label><input name="first_name" required><label>Activatiecode</label><input name="code" placeholder="ABCD-2345" required autocomplete="one-time-code"><button>Verder</button></form><?php else:?><p>Welkom <strong><?=e($member['first_name']??'')?></strong>. Vul je profiel aan en kies je eigen wachtwoord.</p><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="complete"><label>Persoonlijk e-mailadres *</label><input type="email" name="email" required><label>Geboortedatum *</label><input type="date" name="birth_date" value="<?=e($member['birth_date']??'')?>" required><label>Gewicht (kg) *</label><input type="number" min="20" max="250" step="0.1" name="weight_kg" value="<?=e((string)($member['weight_kg']??''))?>" required><label>GSM</label><input name="mobile" value="<?=e($member['mobile']??'')?>"><label>Kies een wachtwoord *</label><div class="pw"><input type="password" name="password" minlength="10" required><button type="button" id="eye">👁</button></div><button>Profiel activeren</button></form><?php endif;?><p><a href="/login.php">← Gewone login</a></p></main><script>const e=document.getElementById('eye');if(e)e.onclick=()=>{const i=e.parentElement.querySelector('input');i.type=i.type==='password'?'text':'password';};</script></body></html>